using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.ML;
using TicketClassifier.Models;

namespace TicketClassifier.Controllers;

[ApiController]
[Route("api/[controller]")]
public sealed class TicketController : ControllerBase
{
    private static readonly string[] Labels = ["Technical", "Billing", "General"];

    private readonly PredictionEnginePool<TicketInput, TicketPrediction> _pool;

    public TicketController(PredictionEnginePool<TicketInput, TicketPrediction> pool)
    {
        _pool = pool;
    }

    [HttpPost("classify")]
    public ActionResult Classify([FromBody] TicketRequest request)
    {
        var input = new TicketInput
        {
            Subject = request.Subject,
            Description = request.Description,
            Priority = request.Priority,
        };

        var prediction = _pool.Predict(input);

        var scores = Labels
            .Zip(prediction.Score)
            .ToDictionary(pair => pair.First, pair => pair.Second);

        return Ok(new
        {
            prediction.Category,
            Confidence = prediction.Score.Max(),
            Scores = scores,
        });
    }
}

